// Sàng lọc theo tuổi / giới / nguy cơ — gợi ý tham khảo (chủ yếu theo USPSTF, ADA, KDIGO), bác sĩ quyết định
const SCREEN = [
  {id:'bp', t:'Đo huyết áp', every:12, when:c=>c.age>=18, how:'Mỗi lần khám, ít nhất mỗi năm (18–39 tuổi không nguy cơ: 3–5 năm/lần).'},
  {id:'dm', t:'Sàng lọc đái tháo đường (glucose đói / HbA1c)', every:36, when:c=>!c.has('diabetes') && (c.age>=35 || (c.age>=18 && c.bmi>=23 && (c.has('htn')||c.has('dyslipid')||c.has('cvd')))), how:'Từ 35 tuổi, hoặc sớm hơn nếu thừa cân (BMI ≥ 23 ở người châu Á) kèm yếu tố nguy cơ. Bình thường: lặp lại mỗi 3 năm.'},
  {id:'lipid', t:'Bilan mỡ máu', every:60, when:c=>c.age>=40 && c.age<=75 && !c.has('dyslipid'), how:'40–75 tuổi: mỗi 5 năm; dày hơn nếu có ĐTĐ, THA, hút thuốc.'},
  {id:'crc', t:'Ung thư đại trực tràng', every:120, when:c=>(c.age>=45 && c.age<=75) || (c.fam('colon') && c.age>=40), how:'45–75 tuổi: nội soi đại tràng mỗi 10 năm, hoặc xét nghiệm máu ẩn trong phân (FIT) mỗi năm. Có người thân bị ung thư đại tràng: bắt đầu từ 40 tuổi.'},
  {id:'gastric', t:'Nội soi dạ dày', every:36, when:c=>c.age>=40 && (c.fam('stomach') || c.has('peptic')), how:'Gợi ý theo thực hành khu vực châu Á (tỉ lệ ung thư dạ dày cao): ≥ 40 tuổi có triệu chứng, H. pylori hoặc người thân bị ung thư dạ dày. Bình thường: nhắc lại sau 2–3 năm.'},
  {id:'cervix', t:'Ung thư cổ tử cung (Pap / HPV)', every:36, when:c=>c.sex==='Nữ' && c.age>=21 && c.age<=65, how:'21–29 tuổi: Pap mỗi 3 năm; 30–65 tuổi: HPV mỗi 5 năm hoặc Pap mỗi 3 năm.'},
  {id:'breast', t:'Ung thư vú (chụp nhũ ảnh)', every:24, when:c=>c.sex==='Nữ' && ((c.age>=40 && c.age<=74) || (c.fam('breast') && c.age>=35)), how:'40–74 tuổi: mỗi 2 năm; sớm hơn nếu có người thân bị ung thư vú.'},
  {id:'lung', t:'Ung thư phổi (CT ngực liều thấp)', every:12, when:c=>c.age>=50 && c.age<=80 && c.packYears>=20 && (c.smoke==='current' || (c.smoke==='former' && c.quitYears<=15)), how:'50–80 tuổi, hút ≥ 20 bao-năm, đang hút hoặc bỏ < 15 năm: mỗi năm.'},
  {id:'osteo', t:'Loãng xương (đo mật độ xương)', every:24, when:c=>(c.sex==='Nữ' && c.age>=65) || (c.sex==='Nữ' && c.menopause && c.age>=50 && (c.bmi<18.5 || c.smoke!=='never' || c.has('osteoporosis'))) || (c.sex==='Nam' && c.age>=70), how:'Nữ ≥ 65 tuổi; nữ mãn kinh có nguy cơ; cân nhắc ở nam ≥ 70 tuổi.'},
  {id:'hep', t:'Viêm gan B, C (HBsAg, anti-HCV)', every:0, when:c=>c.age>=18 && !c.has('hbv'), how:'Người trưởng thành: ít nhất 1 lần trong đời; lặp lại nếu có nguy cơ.'},
  {id:'hcc', t:'Ung thư gan (siêu âm ± AFP)', every:6, when:c=>c.has('hbv') || c.has('liver'), how:'Viêm gan B mạn, xơ gan: mỗi 6 tháng.'},
  {id:'aaa', t:'Phình động mạch chủ bụng (siêu âm)', every:0, when:c=>c.sex==='Nam' && c.age>=65 && c.age<=75 && c.smoke!=='never', how:'Nam 65–75 tuổi từng hút thuốc: siêu âm 1 lần.'},
  {id:'psa', t:'Thảo luận xét nghiệm PSA', every:24, when:c=>c.sex==='Nam' && c.age>=55 && c.age<=69, how:'Nam 55–69 tuổi: quyết định cùng bệnh nhân sau khi tư vấn lợi/hại.'},
  {id:'mood', t:'Sàng lọc trầm cảm / lo âu (PHQ-9, GAD-7)', every:12, when:c=>c.age>=18, how:'Người trưởng thành: định kỳ, nhất là khi có bệnh mạn tính.'},
  {id:'kidney', t:'Theo dõi thận (creatinin/eGFR + ACR niệu)', every:12, everyFn:c=>c.has('ckd')?6:12, when:c=>c.has('diabetes')||c.has('htn')||c.has('ckd'), how:'ĐTĐ, THA: mỗi năm; bệnh thận mạn G3: 3–6 tháng/lần.'},
  {id:'eye', t:'Khám đáy mắt', every:12, when:c=>c.has('diabetes'), how:'Đái tháo đường: mỗi năm.'},
  {id:'foot', t:'Khám bàn chân', every:12, when:c=>c.has('diabetes'), how:'Đái tháo đường: ít nhất mỗi năm.'},
  {id:'a1c', t:'HbA1c', every:6, when:c=>c.has('diabetes'), how:'Ổn định: 6 tháng/lần; chưa đạt mục tiêu: 3 tháng/lần.'},
  {id:'inr', t:'INR', every:1, when:c=>c.longTag('vka'), how:'Đang dùng kháng vitamin K: ít nhất mỗi 4 tuần khi ổn định.'},
];

const FAM_CANCER = {colon:'Đại trực tràng', stomach:'Dạ dày', breast:'Vú', liver:'Gan', lung:'Phổi'};

// Thư viện mẫu: cat: diet | exercise | rehab | tcm | psych | return | advice; tags: điều kiện gợi ý
const TEMPLATES_SEED = [
 {id:'d_peptic', cat:'diet', title:'Viêm dạ dày', tags:['peptic'], text:'Ăn chậm, nhai kỹ; chia 4–5 bữa nhỏ/ngày, không để quá đói hoặc quá no. Không ăn trong 2–3 giờ trước khi ngủ.\nTránh: rượu bia, cà phê đặc, đồ cay nóng, chua, đồ chiên rán nhiều dầu mỡ, nước có ga; không hút thuốc.\nNên: cơm mềm, cháo, khoai, bánh mì, thịt nạc, cá, trứng luộc/hấp, rau xanh nấu chín, chuối chín.'},
 {id:'d_ckd', cat:'diet', title:'Bệnh thận mạn', tags:['ckd'], text:'Đạm vừa phải (khoảng 0,8 g/kg/ngày), ưu tiên đạm tốt: cá, trứng, thịt nạc, sữa.\nMuối < 5 g/ngày: tránh dưa cà muối, nước chấm mặn, mì gói, đồ hộp, giò chả.\nNếu kali máu cao: hạn chế chuối, cam, khoai, rau củ đậm màu; luộc rau và bỏ nước luộc.\nKhông tự dùng thuốc nam, thực phẩm chức năng khi chưa hỏi bác sĩ.'},
 {id:'d_lose', cat:'diet', title:'Giảm cân', tags:['obese'], text:'Mục tiêu giảm 5–10% cân nặng trong 3–6 tháng (khoảng 0,5–1 kg/tuần), năng lượng theo bảng tính.\nGiảm cơm trắng, bánh kẹo, nước ngọt, trà sữa, rượu bia; tăng rau xanh (≥ 400 g rau quả/ngày), đạm nạc.\nKhông bỏ bữa sáng. Tự cân 1 lần/tuần, cùng giờ, cùng cân.'},
 {id:'d_htn', cat:'diet', title:'Tăng huyết áp (kiểu DASH)', tags:['htn'], text:'Muối < 5 g/ngày (khoảng 1 thìa cà phê, tính cả nước mắm, bột canh).\nNhiều rau, trái cây, ngũ cốc nguyên hạt, sữa ít béo, cá; hạn chế mỡ động vật, thịt chế biến sẵn.\nHạn chế rượu bia; không hút thuốc.'},
 {id:'d_dm', cat:'diet', title:'Đái tháo đường', tags:['diabetes'], text:'Ăn đúng giờ, không bỏ bữa; chia đều tinh bột trong các bữa.\nĐổi một phần cơm trắng sang gạo lứt, khoai, ngô; ăn rau trước, cơm sau.\nTránh nước ngọt, bánh kẹo, trái cây sấy, nước ép; trái cây tươi 1–2 phần nhỏ/ngày.'},
 {id:'d_lipid', cat:'diet', title:'Rối loạn mỡ máu', tags:['dyslipid'], text:'Hạn chế mỡ động vật, da gà, nội tạng, đồ chiên rán, thức ăn nhanh.\nDùng dầu thực vật (đậu nành, oliu, lạc) lượng vừa phải; ăn cá 2–3 bữa/tuần.\nTăng chất xơ: rau, đậu đỗ, yến mạch.'},
 {id:'d_gout', cat:'diet', title:'Gút', tags:['gout'], text:'Hạn chế nội tạng, hải sản, thịt đỏ, nước hầm xương; tránh bia rượu, nước ngọt có đường.\nUống đủ nước (khoảng 2 lít/ngày nếu không suy tim, suy thận nặng).\nGiảm cân từ từ nếu thừa cân.'},
 {id:'e_oa', cat:'exercise', title:'Đau khớp gối – vận động ít tải lên khớp', tags:['oa'], text:'Nên: đạp xe tại chỗ, bơi hoặc đi bộ dưới nước, đi bộ trên đường bằng tốc độ vừa, tập tay, yoga nhẹ.\nTránh: chạy, nhảy, leo cầu thang/leo dốc nhiều, ngồi xổm, quỳ, mang vác nặng.\nTăng dần đến 150 phút/tuần (mỗi lần 20–30 phút); tập sức cơ 2 buổi/tuần.\nNếu đau tăng kéo dài > 2 giờ sau tập → giảm cường độ.'},
 {id:'e_start', cat:'exercise', title:'Người ít vận động – khởi đầu', tags:['sedentary'], text:'Bắt đầu đi bộ 10–15 phút/lần, 1–2 lần/ngày; mỗi tuần tăng thêm 5 phút đến tổng 150 phút/tuần mức vừa (thở nhanh nhưng vẫn nói chuyện được).\nGiảm thời gian ngồi: cứ 30–60 phút đứng dậy đi lại vài phút.'},
 {id:'e_anticoag', cat:'exercise', title:'Đang dùng thuốc chống đông', tags:['tag:anticoag'], text:'Tránh môn đối kháng, dễ va chạm hoặc té ngã (bóng đá, võ thuật, đạp xe nơi đông xe).\nMang giày vững, tập nơi bằng phẳng, đủ ánh sáng.'},
 {id:'r_knee', cat:'rehab', title:'Thoái hoá khớp gối – bài tập tại nhà', tags:['oa'], text:'1. Gồng cơ đùi: ngồi duỗi gối, ép mặt sau gối xuống sàn, giữ 5–10 giây; 10 lần × 3 lượt/ngày.\n2. Nâng chân thẳng: nằm ngửa, gối bên kia co, nâng chân duỗi thẳng cao khoảng 30 cm, giữ 5 giây; 10 lần × 2–3 lượt.\n3. Duỗi gối trên ghế: ngồi ghế, duỗi thẳng gối, giữ 5 giây; 10 lần mỗi bên.\n4. Đạp xe tại chỗ lực cản nhẹ 10–15 phút.\n5. Chườm ấm 15–20 phút trước tập; chườm lạnh nếu sưng nóng sau tập.\nGiới thiệu kỹ thuật viên PHCN nếu không cải thiện sau 4–6 tuần.'},
 {id:'r_back', cat:'rehab', title:'Đau thắt lưng – bài tập tại nhà', tags:[], text:'Duy trì hoạt động nhẹ, tránh nằm lâu.\n1. Nằm ngửa co gối, ép thắt lưng xuống sàn, giữ 5 giây; 10 lần.\n2. Ôm gối vào ngực từng bên, giữ 15–20 giây; 5 lần.\n3. Tư thế "con mèo – con bò" trên hai tay hai gối; 10 lần.\nTránh cúi nhấc vật nặng; khi nhấc: gập gối, giữ lưng thẳng.'},
 {id:'t_epi', cat:'tcm', title:'Đau thượng vị – xoa bóp bấm huyệt', tags:['peptic'], text:'Day bấm huyệt mỗi huyệt 1–2 phút, 2–3 lần/ngày:\n• Trung quản: giữa đường nối rốn và mũi ức.\n• Túc tam lý: dưới khớp gối 3 thốn, ngoài mào xương chày 1 khoát ngón tay.\n• Nội quan: trên lằn chỉ cổ tay 2 thốn, giữa hai gân.\nCó thể châm cứu tại cơ sở YHCT. Báo cho thầy thuốc biết đang dùng thuốc chống đông (nếu có).\nKhông tự dùng thuốc nam/bài thuốc khi đang dùng thuốc chống đông hoặc có bệnh thận nếu chưa hỏi bác sĩ.'},
 {id:'t_knee', cat:'tcm', title:'Đau khớp gối – YHCT', tags:['oa'], text:'Xoa bóp, chườm ngải cứu ấm quanh khớp gối 15–20 phút/ngày.\nBấm huyệt: Độc tỵ, Lương khâu, Huyết hải, Dương lăng tuyền, Túc tam lý.\nChâm cứu / điện châm tại cơ sở YHCT theo liệu trình.'},
 {id:'t_sleep', cat:'tcm', title:'Mất ngủ – YHCT', tags:[], text:'Bấm huyệt Thần môn, Nội quan, An miên trước khi ngủ, mỗi huyệt 1–2 phút.\nNgâm chân nước ấm 15 phút trước khi ngủ.'},
 {id:'p_cbt', cat:'psych', title:'Lo âu – kỹ thuật CBT tại nhà', tags:['depression'], text:'1. Nhật ký suy nghĩ: ghi tình huống → suy nghĩ tự động → cảm xúc (0–10) → bằng chứng ủng hộ/phản bác → suy nghĩ cân bằng hơn.\n2. Thở chậm: hít vào 4 giây, thở ra 6 giây, 5 phút × 2–3 lần/ngày.\n3. Mỗi ngày lên lịch ít nhất 1 hoạt động dễ chịu hoặc có ý nghĩa (hoạt hoá hành vi).\n4. Dành riêng 15 phút/ngày cho "thời gian lo lắng"; ngoài giờ đó, ghi lại và để sau.\nĐánh giá lại PHQ-9/GAD-7 sau 4 tuần; giới thiệu chuyên gia tâm lý nếu không cải thiện.'},
 {id:'p_gut', cat:'psych', title:'Căng thẳng và đau dạ dày', tags:['peptic'], text:'Căng thẳng kéo dài làm triệu chứng dạ dày nặng hơn. Nhận diện tình huống gây căng thẳng, tập thở chậm 5 phút trước bữa ăn, ăn trong không khí thoải mái, không vừa ăn vừa làm việc.'},
 {id:'p_sleep', cat:'psych', title:'Vệ sinh giấc ngủ', tags:[], text:'Đi ngủ và thức dậy cùng giờ, kể cả cuối tuần. Không dùng điện thoại 1 giờ trước ngủ. Không cà phê, trà đặc sau 14 giờ. Chỉ lên giường khi buồn ngủ; nếu không ngủ được sau 20 phút, ra khỏi giường làm việc nhẹ nhàng.'},
 {id:'ret_peptic', cat:'return', title:'Viêm dạ dày – dấu hiệu nguy hiểm', tags:['peptic'], text:'Nôn ra máu hoặc dịch như bã cà phê; đi ngoài phân đen hoặc có máu; đau bụng dữ dội, bụng cứng; chóng mặt, choáng, vã mồ hôi; sút cân không rõ lý do; nuốt nghẹn.'},
 {id:'ret_anticoag', cat:'return', title:'Đang dùng thuốc chống đông', tags:['tag:anticoag'], text:'Chảy máu chân răng/mũi kéo dài, bầm tím nhiều, nước tiểu đỏ, phân đen, đau đầu dữ dội đột ngột, yếu liệt tay chân.'},
 {id:'ret_general', cat:'return', title:'Chung', tags:[], text:'Sốt cao, khó thở, đau ngực; nổi mẩn, phù mặt môi sau khi uống thuốc.'},
 {id:'adv_nsaid', cat:'advice', title:'Không tự mua thuốc giảm đau', tags:['tag:anticoag','ckd','peptic'], text:'Không tự mua thuốc giảm đau kháng viêm (ibuprofen, diclofenac, meloxicam…), thuốc nam, thực phẩm chức năng khi chưa hỏi bác sĩ.'},
 {id:'adv_psych', cat:'advice', title:'Tâm bệnh', tags:['depression','bipolar','insomnia','anorexia','bulimia','tag:ssri','tag:snri'], text:'Uống thuốc đúng giờ, đủ liều; không tự ý ngừng thuốc. Tránh mang thai trong thời gian sử dụng thuốc. Báo bác sĩ ngay lập tức khi xuất hiện triệu chứng bất thường (nôn, tiêu chảy, đau bụng, vàng da, rối loạn ý thức, co giật, sốt cao, mẩn ngứa, đau ngực, khó thở, đau đầu, chóng mặt, yếu liệt, tê bì tay chân…) hoặc tác dụng phụ khi sử dụng thuốc khác. Mang theo phiếu này và các kết quả xét nghiệm khi tái khám.\nĂn chế độ ăn Địa Trung Hải, thức ăn mềm, dễ tiêu; giảm đường, giảm ngọt; tránh chất kích thích; uống đủ nước; tránh nước ép bưởi.\nLập lịch hoạt động có niềm vui và có mục đích, tăng dần mức độ. Hoạt động thể lực 30–45 phút/ngày × 3–5 ngày/tuần.\nĐi ngủ và thức dậy vào giờ cố định, ngủ đủ 8–9 giờ/ngày. Ra nắng vào buổi sáng. Tập luyện cách thích nghi, đối phó với stress.'},
 {id:'adv_general', cat:'advice', title:'Lời dặn chung', tags:[], text:'Uống thuốc đúng giờ, đủ liều; không tự ý ngừng thuốc. Mang theo phiếu này và các kết quả xét nghiệm khi tái khám.'},
];
